Object.assign(window.CODELAB_OFFLINE_PACKS,{"topic-13jun2352equalrowandcolumnpairs":{"key":"topic-13jun2352equalrowandcolumnpairs","number":null,"title":"13 JUN 2352 Equal Row and Column Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"13-JUN 2352 Equal Row and Column Pairs.py","code":"class Solution:\n    def equalPairs(self, grid: List[List[int]]) -> int:\n        result, n = 0, len(grid)\n        # Keep track of the frequency of each row.\n        rowCounter = collections.Counter(tuple(row) for row in grid)\n        # Add up the frequency of each column in map.\n        for c in range(n):\n            col = [grid[i][c] for i in range(n)]\n            result += rowCounter[tuple(col)]\n        return result","hash":"1ab9f574c207429f45843c341025d63e76ecdc4ebcd4cc850d00b6d45a06a541","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/13-JUN 2352 Equal Row and Column Pairs.py"}]}],"sources":["solutions"]},"topic-13may2466countwaystobuildgoodstrings":{"key":"topic-13may2466countwaystobuildgoodstrings","number":null,"title":"13 MAY 2466 Count Ways To Build Good Strings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"13-MAY 2466 Count Ways To Build Good Strings.py","code":"class Solution:\n    def countGoodStrings(self, low: int, high: int, zero: int, one: int) -> int:\n        # Use dp[i] to record to number of good strings of length i.\n        dp = [1] + [0] * (high)\n        mod = 10 ** 9 + 7\n        \n        # Iterate over each length `end`.\n        for end in range(1, high + 1):\n            # check if the current string can be made by append zero `0`s or one `1`s.\n            if end >= zero:\n                dp[end] += dp[end - zero]\n            if end >= one:\n                dp[end] += dp[end - one]\n            dp[end] %= mod\n        \n        # Add up the number of strings with each valid length [low ~ high].\n        return sum(dp[low : high + 1]) % mod","hash":"0e56b8079b83fb9c839073373dd03e52e88a97bc9fba0cd31bbfd6ef04b864ca","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/13-MAY 2466 Count Ways To Build Good Strings.py"}]}],"sources":["solutions"]},"topic-13nov2785sortvowelsinastring":{"key":"topic-13nov2785sortvowelsinastring","number":null,"title":"13 NOV 2785 Sort Vowels in a String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"13-NOV 2785 Sort Vowels in a String.py","code":"class Solution:\n    def sortVowels(self, s: str) -> str:\n        VOWELS = set(['A', 'E', 'I', 'O', 'U', 'a', 'e', 'i', 'o', 'u'])\n        vowelList = []\n        for char in s:\n            if char in VOWELS:\n                vowelList.append(char)\n        vowelList.sort()\n        result, vowelIndex = [], 0\n        for char in s:\n            if char in VOWELS:\n                result.append(vowelList[vowelIndex])\n                vowelIndex += 1\n            else:\n                result.append(char)\n        return ''.join(result)","hash":"a47990febf380751042658c946b60dfd636126af82679f14f311c9143734ed23","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/13-NOV 2785 Sort Vowels in a String.py"}]}],"sources":["solutions"]},"topic-13oct746mincostclimbingstairs":{"key":"topic-13oct746mincostclimbingstairs","number":null,"title":"13 OCT 746 Min Cost Climbing Stairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"13-OCT 746 Min Cost Climbing Stairs.py","code":"class Solution:\n    def minCostClimbingStairs(self, cost: List[int]) -> int:\n        n = len(cost)\n        dp = [cost[0], cost[1], 0]\n        for i in range(2, n):\n            dp[i % 3] = cost[i] + min(dp[(i - 1) % 3], dp[(i - 2) % 3])\n        return min(dp[(n - 1) % 3], dp[(n - 2) % 3])","hash":"e19cf71c7fd28656b4beb187c06c55062d2c8dae8fa56bdad4e308d0c1754588","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/13-OCT 746 Min Cost Climbing Stairs.py"}]}],"sources":["solutions"]},"topic-13sep135candy":{"key":"topic-13sep135candy","number":null,"title":"13 SEP 135 Candy","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"13-SEP 135 Candy.py","code":"class Solution:\n    def candy(self, ratings: List[int]) -> int:\n        ratingsLength = len(ratings)\n        if ratingsLength == 0:\n            return 0\n        candies = [1] * ratingsLength\n        for i in range(1, ratingsLength):\n            if ratings[i] > ratings[i - 1]:\n                candies[i] = candies[i - 1] + 1\n        totalCandies = candies[ratingsLength - 1]\n        for i in range(ratingsLength - 2, -1, -1):\n            if ratings[i] > ratings[i + 1]:\n                candies[i] = max(candies[i], candies[i + 1] + 1)\n            totalCandies += candies[i]\n        return totalCandies","hash":"72b210b26bc360c8302ef852ba54c22d2435ba90275eb1f2c66b83af6dd672e4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/13-SEP 135 Candy.py"}]}],"sources":["solutions"]},"topic-132pattern":{"key":"topic-132pattern","number":null,"title":"132 Pattern","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"132 Pattern.py","code":"class Solution:\n    def find132pattern(self, nums: List[int]) -> bool:\n        numberOfItems = len(nums)\n        if numberOfItems < 3:\n            return False\n        stack, minArray = [], [0] * numberOfItems\n        minArray[0] = nums[0]\n        for i in range(1, numberOfItems):\n            minArray[i] = min(minArray[i - 1], nums[i])\n        for i in range(numberOfItems - 1, -1, -1):\n            if nums[i] > minArray[i]:\n                while stack and stack[-1] <= minArray[i]:\n                    stack.pop()\n                if stack and stack[-1] < nums[i]:\n                    return True\n                stack.append(nums[i])\n        return False","hash":"ea873e7adadfedadc563a1e3cd81065163fe65fb388c41eba48366e1807d5cdf","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/132 Pattern.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/132 Pattern.py"}]}],"sources":["solutions"]},"topic-14aug215kthlargestelementinanarray":{"key":"topic-14aug215kthlargestelementinanarray","number":null,"title":"14 AUG 215 Kth Largest Element in an Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"14-AUG 215 Kth Largest Element in an Array.py","code":"class Solution:\n    def findKthLargest(self, nums: List[int], k: int) -> int:\n        return heapq.nlargest(k, nums)[-1]","hash":"710349f60a51cb716347e30ebc3d8727db4a73f4bdccc8c7d3160578bcd103e2","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/14-AUG 215 Kth Largest Element in an Array.py"}]}],"sources":["solutions"]},"topic-14jul1218longestarithmeticsubsequenceofgivendifference":{"key":"topic-14jul1218longestarithmeticsubsequenceofgivendifference","number":null,"title":"14 JUL 1218 Longest Arithmetic Subsequence of Given Difference","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"14-JUL 1218 Longest Arithmetic Subsequence of Given Difference.py","code":"class Solution:\n    def longestSubsequence(self, arr: List[int], difference: int) -> int:\n        dp = defaultdict(int)\n        result = 1\n        for num in arr:\n            beforeNum = dp[num - difference]\n            dp[num] = beforeNum + 1\n            result = max(result, dp[num])\n        return result","hash":"0023c108d5351153d8b88116fcf1331a3e1e6ee073d35d340991494c9c08e45d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/14-JUL 1218 Longest Arithmetic Subsequence of Given Difference.py"}]}],"sources":["solutions"]},"topic-14jun530minimumabsolutedifferenceinbst":{"key":"topic-14jun530minimumabsolutedifferenceinbst","number":null,"title":"14 JUN 530 Minimum Absolute Difference in BST","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"14-JUN 530 Minimum Absolute Difference in BST.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def getMinimumDifference(self, root: TreeNode) -> int:\n        result, prev = float('inf'), float('-inf')\n        def inorder(node):\n            nonlocal result, prev\n            if node:\n                inorder(node.left)\n                result = min(result, node.val - prev)\n                prev = node.val\n                inorder(node.right)\n        inorder(root)\n        return result","hash":"2c515c215492885c264d9ab53219b72122191112885bf75dd20626dd5772aca2","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/14-JUN 530 Minimum Absolute Difference in BST.py"}]}],"sources":["solutions"]},"topic-14may1799maximizescoreafternoperations":{"key":"topic-14may1799maximizescoreafternoperations","number":null,"title":"14 MAY 1799 Maximize Score After N Operations","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"14-MAY 1799 Maximize Score After N Operations.py","code":"class Solution:\n    def maxScore(self, nums: List[int]) -> int:\n        @lru_cache(None)\n        def backtrack(mask: int, pairsPicked: int) -> int:\n            # If we have picked all the numbers from 'nums' array, we can't get more score.\n            if 2 * pairsPicked == len(nums):\n                return 0\n            maxScore = 0\n            # Iterate on 'nums' array to pick the first and second number of the pair.\n            for firstIndex in range(len(nums)):\n                for secondIndex in range(firstIndex + 1, len(nums)):\n                    # If the numbers are same, or already picked, then we move to next number.\n                    if (mask >> firstIndex) & 1 == 1 or (mask >> secondIndex) & 1 == 1:\n                        continue\n                    # Both numbers are marked as picked in this new mask.\n                    newMask = mask | (1 << firstIndex) | (1 << secondIndex)\n                    # Calculate score of current pair of numbers, and the remaining array.\n                    currScore = (pairsPicked + 1) * math.gcd(nums[firstIndex], nums[secondIndex])\n                    remainingScore = backtrack(newMask, pairsPicked + 1)\n                    # Store the maximum score.\n                    maxScore = max(maxScore, currScore + remainingScore)\n                    # We will use old mask in loop's next interation,\n                    # means we discarded the picked number and backtracked.\n            return maxScore\n        return backtrack(0, 0)","hash":"ca660b23c939ee120cd36ce3b8aa06e1dbf12223f7c7aad99e020f534ab728d5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/14-MAY 1799 Maximize Score After N Operations.py"}]}],"sources":["solutions"]},"topic-14nov1930uniquelength3palindromicsubsequences":{"key":"topic-14nov1930uniquelength3palindromicsubsequences","number":null,"title":"14 NOV 1930 Unique Length 3 Palindromic Subsequences","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"14-NOV 1930 Unique Length-3 Palindromic Subsequences.py","code":"class Solution:\n    def countPalindromicSubsequence(self, s: str) -> int:\n        letters = set(s)\n        ans = 0\n        for letter in letters:\n            i, j = s.index(letter), s.rindex(letter)\n            between = set()\n            for k in range(i + 1, j):\n                between.add(s[k])\n            ans += len(between)\n        return ans","hash":"615b8c77a20611ba808e14e71c67d80e4617630a810f7e6de01fcbbcbf967477","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/14-NOV 1930 Unique Length-3 Palindromic Subsequences.py"}]}],"sources":["solutions"]},"topic-14oct2742paintingthewalls":{"key":"topic-14oct2742paintingthewalls","number":null,"title":"14 OCT 2742 Painting the Walls","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"14-OCT 2742 Painting the Walls.py","code":"class Solution:\n    def paintWalls(self, cost: List[int], time: List[int]) -> int:\n        @lru_cache(None)\n        def dp(i, remain):\n            if remain <= 0:\n                return 0\n            if i == len(cost):\n                return inf\n            paint = cost[i] + dp(i + 1, remain - 1 - time[i])\n            dontPaint = dp(i + 1, remain)\n            return min(paint, dontPaint)\n        return dp(0, len(cost))","hash":"c7dd429c695ff285e680734d1798fb88663e166d6489c3f504098c7e159601f1","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/14-OCT 2742 Painting the Walls.py"}]}],"sources":["solutions"]},"topic-14sep332reconstructitinerary":{"key":"topic-14sep332reconstructitinerary","number":null,"title":"14 SEP 332 Reconstruct Itinerary","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"14-SEP 332 Reconstruct Itinerary.py","code":"class Solution:\n    def findItinerary(self, tickets: List[List[str]]) -> List[str]:\n        flightGraph, itinerary = defaultdict(list), []\n        # Populate the flight graph using ticket information\n        for fromAirport, toAirport in tickets:\n            flightGraph[fromAirport].append(toAirport)\n        # Sort destinations in reverse order to visit lexical smaller destinations first\n        for destinations in flightGraph.values():\n            destinations.sort(reverse = True)\n        # Depth-First Search to traverse the flight itinerary\n        def dfs(airport: string):\n            destinations = flightGraph[airport]\n            # Visit destinations in lexical order\n            while destinations:\n                dfs(destinations.pop())\n            # Add the current airport to the itinerary after visiting all destinations\n            itinerary.append(airport)\n        # Start the DFS from the JFK airport\n        dfs('JFK')\n        # Reverse the itinerary to get the correct order\n        itinerary.reverse()\n        return itinerary","hash":"550b3770e165be29813b73bc8c98f0831d2115a3c219ea3565464e7f1754cfb0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/14-SEP 332 Reconstruct Itinerary.py"}]}],"sources":["solutions"]},"topic-15aug86partitionlist":{"key":"topic-15aug86partitionlist","number":null,"title":"15 AUG 86 Partition List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"15-AUG 86 Partition List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def partition(self, head: ListNode, x: int) -> ListNode:\n        before = beforeHead = ListNode(0)\n        after = afterHead = ListNode(0)\n        while head:\n            if head.val < x:\n                before.next = head\n                before = before.next\n            else:\n                after.next = head\n                after = after.next\n            head = head.next\n        after.next = None\n        before.next = afterHead.next\n        return beforeHead.next","hash":"fca35d86079b9cd50d049a472f123ccdd9a9edea3e4ee69da2486578087d7a8c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/15-AUG 86 Partition List.py"}]}],"sources":["solutions"]},"topic-15jul1751maximumnumberofeventsthatcanbeattendedii":{"key":"topic-15jul1751maximumnumberofeventsthatcanbeattendedii","number":null,"title":"15 JUL 1751 Maximum Number of Events That Can Be Attended II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"15-JUL 1751 Maximum Number of Events That Can Be Attended II.py","code":"class Solution:\n    def maxValue(self, events: List[List[int]], k: int) -> int:\n        events.sort()\n        n = len(events)\n        starts = [start for start, end, value in events]\n        dp = [[-1] * n for _ in range(k + 1)]\n        \n        def dfs(cur_index, count):\n            if count == 0 or cur_index == n:\n                return 0\n            if dp[count][cur_index] != -1:\n                return dp[count][cur_index]\n\n            # Find the nearest available event after attending event 0.\n\n            next_index = bisect_right(starts, events[cur_index][1])\n            dp[count][cur_index] = max(dfs(cur_index + 1, count), events[cur_index][2] + dfs(next_index, count - 1))\n            return dp[count][cur_index]\n        \n        return dfs(0, k)","hash":"be796fb4a5df3ab805ea4b49d258985187c72a306ff2619c11291c15631da6e3","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/15-JUL 1751 Maximum Number of Events That Can Be Attended II.py"}]}],"sources":["solutions"]},"topic-15jun1161maximumlevelsumofabinarytree":{"key":"topic-15jun1161maximumlevelsumofabinarytree","number":null,"title":"15 JUN 1161 Maximum Level Sum of a Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"15-JUN 1161 Maximum Level Sum of a Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def maxLevelSum(self, root: TreeNode) -> int:\n        levelSumMap = defaultdict(int)\n        \n        def dfs(node, level):\n            if node:\n                levelSumMap[level] += node.val\n                dfs(node.left, level + 1)\n                dfs(node.right, level + 1)\n        \n        dfs(root, 1)\n        levelSum = max(levelSumMap.values())\n        for level, s in levelSumMap.items():\n            if s == levelSum:\n                return level","hash":"a6f0bf37d7905f23bf9cbc10a7bd04ec6ecd0adfbfaf48f7415165b5c323b344","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/15-JUN 1161 Maximum Level Sum of a Binary Tree.py"}]}],"sources":["solutions"]},"topic-15may1721swappingnodesinalinkedlist":{"key":"topic-15may1721swappingnodesinalinkedlist","number":null,"title":"15 MAY 1721 Swapping Nodes in a Linked List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"15-MAY 1721 Swapping Nodes in a Linked List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def swapNodes(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:\n        listLength, frontNode, endNode, currentNode = 0, None, None, head\n        while currentNode != None:\n            listLength += 1\n            if endNode != None:\n                endNode = endNode.next\n            if listLength == k:\n                frontNode = currentNode\n                endNode = head\n            currentNode = currentNode.next\n        frontNode.val, endNode.val = endNode.val, frontNode.val\n        return head","hash":"d0037713d924972d700b488f1f81b1230dbbbac76ca86040e370f11f584e90c0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/15-MAY 1721 Swapping Nodes in a Linked List.py"}]}],"sources":["solutions"]},"topic-15nov1846maximumelementafterdecreasingandrearranging":{"key":"topic-15nov1846maximumelementafterdecreasingandrearranging","number":null,"title":"15 NOV 1846 Maximum Element After Decreasing and Rearranging","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"15-NOV 1846 Maximum Element After Decreasing and Rearranging.py","code":"class Solution:\n    def maximumElementAfterDecrementingAndRearranging(self, arr: List[int]) -> int:\n        arr = sorted(arr)\n        if arr[0] != 1:\n            arr[0] = 1\n        for i in range(1, len(arr)):\n            if abs(arr[i] - arr[i - 1]) > 1:\n                arr[i] = arr[i - 1] + 1\n        return arr[-1]","hash":"25489c3ca7aa8ef5ec5e713598f93c3dff1ad85c9f6d659dcc6bf433dbc454d6","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/15-NOV 1846 Maximum Element After Decreasing and Rearranging.py"}]}],"sources":["solutions"]},"topic-15oct1269numberofwaystostayinthesameplaceaftersomesteps":{"key":"topic-15oct1269numberofwaystostayinthesameplaceaftersomesteps","number":null,"title":"15 OCT 1269 Number of Ways to Stay in the Same Place After Some Steps","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"15-OCT 1269 Number of Ways to Stay in the Same Place After Some Steps.py","code":"class Solution:\n    def numWays(self, steps: int, arrLen: int) -> int:\n        MOD = 10 ** 9 + 7\n        @lru_cache(None)\n        def dp(current, remain):\n            if remain == 0:\n                if current == 0:\n                    return 1\n                return 0\n            result = dp(current, remain - 1)\n            if current > 0:\n                result = (result + dp(current - 1, remain - 1)) % MOD\n            if current < arrLen - 1:\n                result = (result + dp(current + 1, remain - 1)) % MOD\n            return result\n        return dp(0, steps)","hash":"bbc7178cc18c6fd9f9ce4d74635175ced2275d5b2c36b62c35d8d031fbc63322","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/15-OCT 1269 Number of Ways to Stay in the Same Place After Some Steps.py"}]}],"sources":["solutions"]},"topic-15sep1584mincosttoconnectallpoints":{"key":"topic-15sep1584mincosttoconnectallpoints","number":null,"title":"15 SEP 1584 Min Cost to Connect All Points","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"15-SEP 1584 Min Cost to Connect All Points.py","code":"class Solution:\n    def minCostConnectPoints(self, points: List[List[int]]) -> int:\n        getDist = lambda p1, p2: abs(p2[0] - p1[0]) + abs(p2[1] - p1[1])\n        numberOfPoints = len(points)\n        parent, heap, edgesCovered, cost = [-1] * numberOfPoints, [], 0, 0\n        def find(x):\n            if parent[x] == -1:\n                return x\n            parent[x] = find(parent[x])\n            return parent[x]\n        def union(x, y):\n            px, py = find(x), find(y)\n            parent[py] = px\n        for p1 in range(numberOfPoints):\n            for p2 in range(p1 + 1, numberOfPoints):\n                heap.append((getDist(points[p1], points[p2]), p1, p2))\n        heapify(heap)\n        while edgesCovered < numberOfPoints - 1:\n            d, p1, p2 = heappop(heap)\n            if find(p1) != find(p2):\n                cost += d\n                edgesCovered += 1\n                union(p1, p2)\n        return cost","hash":"60dbe5231ebc4925a5555d2f1679942d85c46bd92e8a3af3224c4f54ab86fe6e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/15-SEP 1584 Min Cost to Connect All Points.py"}]}],"sources":["solutions"]},"topic-16aug239slidingwindowmaximum":{"key":"topic-16aug239slidingwindowmaximum","number":null,"title":"16 AUG 239 Sliding Window Maximum","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"16-AUG 239 Sliding Window Maximum.py","code":"class Solution:\n    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:\n        if len(nums) * k == 0:\n            return []\n        if k == 1:\n            return nums\n        dequeue, result, maxIndex = deque(), [], 0\n        def cleanDeque(i):\n            if dequeue and dequeue[0] == i - k:\n                dequeue.popleft()\n            while dequeue and nums[i] > nums[dequeue[-1]]:\n                dequeue.pop()\n        for i in range(k):\n            cleanDeque(i)\n            dequeue.append(i)\n            if nums[i] > nums[maxIndex]:\n                maxIndex = i\n        result.append(nums[maxIndex])\n        for i in range(k, len(nums)):\n            cleanDeque(i)\n            dequeue.append(i)\n            result.append(nums[dequeue[0]])\n        return result","hash":"fc4a724520141071290aedfa3e66712f181d7e6538f1868b73ebadbe3ccdd398","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/16-AUG 239 Sliding Window Maximum.py"}]}],"sources":["solutions"]},"topic-16jul1125smallestsufficientteam":{"key":"topic-16jul1125smallestsufficientteam","number":null,"title":"16 JUL 1125 Smallest Sufficient Team","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"16-JUL 1125 Smallest Sufficient Team.py","code":"class Solution:\n    def smallestSufficientTeam(self, req_skills: List[str], people: List[List[str]]) -> List[int]:\n        n, m, skillId = len(people), len(req_skills), dict()\n        for i, skill in enumerate(req_skills):\n            skillId[skill] = i\n        skillsMaskOfPerson = [0] * n\n        for person in range(n):\n            for skill in people[person]:\n                skillsMaskOfPerson[person] |= (1 << skillId[skill])\n        dp = [(1 << n) - 1] * (1 << m)\n        dp[0] = 0\n        for skillsMask in range(1, 1 << m):\n            for person in range(n):\n                smallerSkillsMask = skillsMask & ~skillsMaskOfPerson[person]\n                if smallerSkillsMask != skillsMask:\n                    # currentMask is the mask that represents the new team once you add the current person.\n                    currentMask = dp[smallerSkillsMask] | (1 << person)\n                    if currentMask.bit_count() < dp[skillsMask].bit_count():\n                        dp[skillsMask] = currentMask\n        resultMask = dp[(1 << m) - 1]\n        result = []\n        for person in range(n):\n            if (resultMask >> person) & 1:\n                result.append(person)\n        return result","hash":"ebb49c367da9a35274c9a0ffffda665df468fa3675223fffb5cb616a19fbfd66","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/16-JUL 1125 Smallest Sufficient Team.py"}]}],"sources":["solutions"]},"topic-16jun1569numberofwaystoreorderarraytogetsamebst":{"key":"topic-16jun1569numberofwaystoreorderarraytogetsamebst","number":null,"title":"16 JUN 1569 Number of Ways to Reorder Array to Get Same BST","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"16-JUN 1569 Number of Ways to Reorder Array to Get Same BST.py","code":"class Solution:\n    def numOfWays(self, nums: List[int]) -> int:\n        def getNumberOfDifferentWaysUsingFirstElementAsRoot(nums):\n            if len(nums) <= 2:\n                return 1\n            leftElements = [num for num in nums[1:] if num < nums[0]]\n            rightElements = [num for num in nums[1:] if num > nums[0]]\n            return comb(len(leftElements) + len(rightElements), len(rightElements)) * getNumberOfDifferentWaysUsingFirstElementAsRoot(leftElements) * getNumberOfDifferentWaysUsingFirstElementAsRoot(rightElements)\n        \n        return (getNumberOfDifferentWaysUsingFirstElementAsRoot(nums) - 1) % (10**9 + 7)","hash":"382bac9c9a40d29ec803b53221f20590f97cbe15347d0406bb2455885387f549","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/16-JUN 1569 Number of Ways to Reorder Array to Get Same BST.py"}]}],"sources":["solutions"]},"topic-16may24swapnodesinpairs":{"key":"topic-16may24swapnodesinpairs","number":null,"title":"16 MAY 24 Swap Nodes in Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"16-MAY 24 Swap Nodes in Pairs.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def swapPairs(self, head: Optional[ListNode]) -> Optional[ListNode]:\n        prev = ListNode()\n        prev.next = head\n        newHead = prev\n        temp = head\n        while temp and temp.next:\n            nextSetNode = temp.next.next\n            currSetHead = temp.next\n            temp.next.next = temp\n            temp.next = nextSetNode\n            temp = nextSetNode\n            prev.next = currSetHead\n            prev = prev.next.next\n        return newHead.next","hash":"aa3288aa802bedbb1b3254eafe6d17debddf6ad81154a7fc42c444bb9a3b2a16","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/16-MAY 24 Swap Nodes in Pairs.py"}]}],"sources":["solutions"]},"topic-16nov1980finduniquebinarystring":{"key":"topic-16nov1980finduniquebinarystring","number":null,"title":"16 NOV 1980 Find Unique Binary String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"16-NOV 1980 Find Unique Binary String.py","code":"class Solution:\n    def findDifferentBinaryString(self, nums: List[str]) -> str:\n        result = []\n        for i in range(len(nums)):\n            current = nums[i][i]\n            result.append('1' if current == '0' else '0')\n        return ''.join(result)","hash":"6b5b964b927b69beb9edc0d6b919ccd602879aaa407d8d68b7429fbaba95dd5b","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/16-NOV 1980 Find Unique Binary String.py"}]}],"sources":["solutions"]},"topic-16oct119pascalstriangleii":{"key":"topic-16oct119pascalstriangleii","number":null,"title":"16 OCT 119 Pascal's Triangle II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"16-OCT 119 Pascal's Triangle II.py","code":"class Solution:\n    def getRow(self, rowIndex: int) -> List[int]:\n        row = [1]\n        for k in range(1, rowIndex + 1):\n            row.append(int((row[-1] * (rowIndex - k + 1)) / k))\n        return row","hash":"107c2d27dfe4a0961b7b33b97e3dbab826858d0961a39ed2a01229b9e8159415","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/16-OCT 119 Pascal's Triangle II.py"}]}],"sources":["solutions"]},"topic-16sep1631pathwithminimumeffort":{"key":"topic-16sep1631pathwithminimumeffort","number":null,"title":"16 SEP 1631 Path With Minimum Effort","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"16-SEP 1631 Path With Minimum Effort.py","code":"class Solution:\n    def minimumEffortPath(self, heights: List[List[int]]) -> int:\n        rows, cols = len(heights), len(heights[0])\n        dist = [[float('inf')] * cols for _ in range(rows)]\n        dist[0][0], heap = 0, [(0, 0, 0)]\n        while heap:\n            distance, row, col = heappop(heap)\n            if row == rows - 1 and col == cols - 1:\n                return distance\n            if distance > dist[row][col]:\n                continue\n            for r, c in [(row - 1, col), (row, col - 1), (row + 1, col), (row, col + 1)]:\n                if 0 <= r < rows and 0 <= c < cols:\n                    tempDistance = max(distance, abs(heights[row][col] - heights[r][c]))\n                    if tempDistance < dist[r][c]:\n                        dist[r][c] = tempDistance\n                        heappush(heap, (tempDistance, r, c))","hash":"f0bf25c1257baf7f4dcf0824c697618e93082952cff6a7f6ec4c245f6ad7a900","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/16-SEP 1631 Path With Minimum Effort.py"}]}],"sources":["solutions"]},"topic-17aug54201matrix":{"key":"topic-17aug54201matrix","number":null,"title":"17 AUG 542 01 Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"17-AUG 542 01 Matrix.py","code":"class Solution:\n    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:\n        rows, cols = len(mat), len(mat[0])\n        dist = [[float('inf')] * cols for _ in range(rows)]\n        for i in range(rows):\n            for j in range(cols):\n                if mat[i][j] == 0:\n                    dist[i][j] = 0\n                else:\n                    if i > 0:\n                        dist[i][j] = min(dist[i][j], dist[i - 1][j] + 1)\n                    if j > 0:\n                        dist[i][j] = min(dist[i][j], dist[i][j - 1] + 1)\n        for i in range(rows - 1, -1, -1):\n            for j in range(cols - 1, -1, -1):\n                if i < rows - 1:\n                    dist[i][j] = min(dist[i][j], dist[i + 1][j] + 1)\n                if j < cols - 1:\n                    dist[i][j] = min(dist[i][j], dist[i][j + 1] + 1)\n        return dist","hash":"d2f73890653d293a4276fa308ff8c9aa1a3b53b948fd648094b16ab4f180ba1b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/17-AUG 542 01 Matrix.py"}]}],"sources":["solutions"]},"topic-17jul445addtwonumbersii":{"key":"topic-17jul445addtwonumbersii","number":null,"title":"17 JUL 445 Add Two Numbers II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"17-JUL 445 Add Two Numbers II.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:\n        def reverseList(node):\n            prev = None\n            while node:\n                temp = node.next\n                node.next = prev\n                prev = node\n                node = temp\n            return prev\n        l1 = reverseList(l1)\n        l2 = reverseList(l2)\n        carry, head = 0, None\n        while l1 or l2:\n            x1 = l1.val if l1 is not None else 0\n            x2 = l2.val if l2 is not None else 0\n            currentSum = carry + x1 + x2\n            val = currentSum % 10\n            carry = currentSum // 10\n            currNode = ListNode(val)\n            currNode.next = head\n            head = currNode\n            l1 = l1.next if l1 is not None else None\n            l2 = l2.next if l2 is not None else None\n        if carry:\n            currNode = ListNode(carry)\n            currNode.next = head\n            head = currNode\n        return head","hash":"dd3b3b09438404d993bb3ec4aa829365fbc0ed8e9cc7e588ae6bc46038d5d270","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/17-JUL 445 Add Two Numbers II.py"}]}],"sources":["solutions"]},"topic-17jun1187makearraystrictlyincreasing":{"key":"topic-17jun1187makearraystrictlyincreasing","number":null,"title":"17 JUN 1187 Make Array Strictly Increasing","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"17-JUN 1187 Make Array Strictly Increasing.py","code":"class Solution:\n    def makeArrayIncreasing(self, arr1: List[int], arr2: List[int]) -> int:\n        arr2.sort()\n\n        @lru_cache(None)\n        def dfs(i: int, prev: int) -> int:\n            if i == len(arr1):\n                return 0\n            cost = float('inf')\n            # If arr1[i] is already greater than prev, we can leave it be.\n            if arr1[i] > prev:\n                cost = dfs(i + 1, arr1[i])\n            # Find a replacement with the smallest value in arr2.\n            index = bisect.bisect_right(arr2, prev)\n            # Replace arr1[i], with a cost of 1 operation.\n            if index < len(arr2):\n                cost = min(cost, 1 + dfs(i + 1, arr2[index]))\n            return cost\n        \n        result = dfs(0, -1)\n        return result if result < float('inf') else -1","hash":"156e3e82d4c628d045ff5748162640796e896f2b66169b294b55e2adbf932af6","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/17-JUN 1187 Make Array Strictly Increasing.py"}]}],"sources":["solutions"]},"topic-17may2130maximumtwinsumofalinkedlist":{"key":"topic-17may2130maximumtwinsumofalinkedlist","number":null,"title":"17 MAY 2130 Maximum Twin Sum of a Linked List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"17-MAY 2130 Maximum Twin Sum of a Linked List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def pairSum(self, head: Optional[ListNode]) -> int:\n        current = head\n        values = []\n\n        while current:\n            values.append(current.val)\n            current = current.next\n        \n        i = 0\n        j = len(values) - 1\n        maximumSum = 0\n        while(i < j):\n            maximumSum = max(maximumSum, values[i] + values[j])\n            i = i + 1\n            j = j - 1\n        \n        return maximumSum","hash":"0b8b77154f703621a133df8797e993745795db96e133e7a7a0a5154005c07fea","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/17-MAY 2130 Maximum Twin Sum of a Linked List.py"}]}],"sources":["solutions"]},"topic-17nov1877minimizemaximumpairsuminarray":{"key":"topic-17nov1877minimizemaximumpairsuminarray","number":null,"title":"17 NOV 1877 Minimize Maximum Pair Sum in Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"17-NOV 1877 Minimize Maximum Pair Sum in Array.py","code":"class Solution:\n    def minPairSum(self, nums: List[int]) -> int:\n        nums.sort()\n        maxSum, N = 0, len(nums)\n        for i in range(N // 2):\n            maxSum = max(maxSum, nums[i] + nums[N - 1 - i])\n        return maxSum","hash":"dfe71306e4235d6da810dd211a9352b380ad942d80d3542c2437c3dd33e407b5","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/17-NOV 1877 Minimize Maximum Pair Sum in Array.py"}]}],"sources":["solutions"]},"topic-17oct1361validatebinarytreenodes":{"key":"topic-17oct1361validatebinarytreenodes","number":null,"title":"17 OCT 1361 Validate Binary Tree Nodes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"17-OCT 1361 Validate Binary Tree Nodes.py","code":"class Solution:\n    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:\n        def findRoot():\n            children = set(leftChild) | set(rightChild)\n            rootsList = []\n            for i in range(n):\n                if i not in children:\n                    rootsList.append(i)\n            return rootsList\n        rootsList = findRoot()\n        if len(rootsList) != 1:\n            return False\n        root = rootsList[0]\n        seen, stack = {root}, [root]\n        while stack:\n            node = stack.pop()\n            for child in [leftChild[node], rightChild[node]]:\n                if child == -1:\n                    continue\n                if child in seen:\n                    return False\n                stack.append(child)\n                seen.add(child)\n        return len(seen) == n","hash":"cd79920e1c1b409f7baa1aff725b8ed70b13cb3a515e034c0d51ff39e7951c4a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/17-OCT 1361 Validate Binary Tree Nodes.py"}]}],"sources":["solutions"]},"topic-17sep847shortestpathvisitingallnodes":{"key":"topic-17sep847shortestpathvisitingallnodes","number":null,"title":"17 SEP 847 Shortest Path Visiting All Nodes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"17-SEP 847 Shortest Path Visiting All Nodes.py","code":"class Solution:\n    def shortestPathLength(self, graph: List[List[int]]) -> int:\n        if len(graph) == 1:\n            return 0\n        n, steps = len(graph), 0\n        endingMask, queue = (1 << n) - 1, [(node, 1 << node) for node in range(n)]\n        seen = set(queue)\n        while queue:\n            nextQueue = []\n            for i in range(len(queue)):\n                node, mask = queue[i]\n                for neighbour in graph[node]:\n                    nextMask = mask | 1 << neighbour\n                    if nextMask == endingMask:\n                        return  1 + steps\n                    if (neighbour, nextMask) not in seen:\n                        seen.add((neighbour, nextMask))\n                        nextQueue.append((neighbour, nextMask))\n            steps += 1\n            queue = nextQueue","hash":"54feddec37b951c1570a1e1e670d6def46a75a7efda9a3aee3517b4c33bc5d2f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/17-SEP 847 Shortest Path Visiting All Nodes.py"}]}],"sources":["solutions"]},"topic-18aug1615maximalnetworkrank":{"key":"topic-18aug1615maximalnetworkrank","number":null,"title":"18 AUG 1615 Maximal Network Rank","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"18-AUG 1615 Maximal Network Rank.py","code":"class Solution:\n    def maximalNetworkRank(self, n: int, roads: List[List[int]]) -> int:\n        adjMatrix, degree, maxNetworkRank = [[0] * n for _ in range(n)], [0] * n, 0\n        for a, b in roads:\n            adjMatrix[a][b] = adjMatrix[b][a] = 1\n            degree[a] += 1\n            degree[b] += 1\n        for i in range(n):\n            for j in range(i + 1, n):\n                maxNetworkRank = max(maxNetworkRank, degree[i] + degree[j] - adjMatrix[i][j])\n        return maxNetworkRank","hash":"2ed1a22deff5d0e537093d38fc88ef9f1f51af57f928996427935e99352cc380","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/18-AUG 1615 Maximal Network Rank.py"}]}],"sources":["solutions"]},"topic-18jul146lrucache":{"key":"topic-18jul146lrucache","number":null,"title":"18 JUL 146 LRU Cache","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"18-JUL 146 LRU Cache.py","code":"class LRUCache(OrderedDict):\n\n    def __init__(self, capacity: int):\n        self._capacity = capacity\n\n    def get(self, key: int) -> int:\n        if key not in self:\n            return -1\n        self.move_to_end(key)\n        return self[key]\n\n    def put(self, key: int, value: int) -> None:\n        if key in self:\n            self.move_to_end(key)\n        self[key] = value\n        if len(self) > self._capacity:\n            self.popitem(last = False)\n\n\n# Your LRUCache object will be instantiated and called as such:\n# obj = LRUCache(capacity)\n# param_1 = obj.get(key)\n# obj.put(key,value)","hash":"455ce34948e6d7eae933f4bbb50202566700f008193e670d72d771f0eb26d4ec","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/18-JUL 146 LRU Cache.py"}]}],"sources":["solutions"]},"topic-18jun2328numberofincreasingpathsinagrid":{"key":"topic-18jun2328numberofincreasingpathsinagrid","number":null,"title":"18 JUN 2328 Number of Increasing Paths in a Grid","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"18-JUN 2328 Number of Increasing Paths in a Grid.py","code":"class Solution:\n    def countPaths(self, grid: List[List[int]]) -> int:\n        m, n, MOD = len(grid), len(grid[0]), 10**9 + 7\n        DIRECTIONS = [(0, 1), (0, -1), (1, 0), (-1, 0)]\n        # Initialize dp, 1 stands for the path made by a cell itself.\n        dp = [[1] * n for _ in range(m)]\n        # Sort all cells by value\n        cellList = [[i, j] for i in range(m) for j in range(n)]\n        cellList.sort(key = lambda x : grid[x[0]][x[1]])\n        # Iterate over the sorted cells, for each cell grid[i][j]\n        for i, j in cellList:\n            # Check its four neighbor cells, if a neighbor cell grid[curr_i][curr_j] has a\n            # larger value, increment dp[curr_i][curr_j] by dp[i][j]\n            for di, dj in DIRECTIONS:\n                curri, currj = i + di, j + dj\n                if 0 <= curri < m and 0 <= currj < n and grid[curri][currj] > grid[i][j]:\n                    dp[curri][currj] += dp[i][j]\n                    dp[curri][currj] %= MOD\n        # Sum over dp[i][j].\n        return sum(sum(row) % MOD for row in dp) % MOD","hash":"6f6323e523424a24adc3a46eaecc3b8856874d92675dc8835314479499ec1b52","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/18-JUN 2328 Number of Increasing Paths in a Grid.py"}]}],"sources":["solutions"]},"topic-18may1557minimumnumberofverticestoreachallnodes":{"key":"topic-18may1557minimumnumberofverticestoreachallnodes","number":null,"title":"18 MAY 1557 Minimum Number of Vertices to Reach All Nodes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"18-MAY 1557 Minimum Number of Vertices to Reach All Nodes.py","code":"class Solution:\n    def findSmallestSetOfVertices(self, n: int, edges: List[List[int]]) -> List[int]:\n        hashSet = {TO for FROM, TO in edges}\n        return [i for i in range(n) if i not in hashSet]","hash":"78e0e54a6cdf243475d114a7a3f770cc257110e81c702f4845fe25ea041afb85","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/18-MAY 1557 Minimum Number of Vertices to Reach All Nodes.py"}]}],"sources":["solutions"]},"topic-18nov1838frequencyofthemostfrequentelement":{"key":"topic-18nov1838frequencyofthemostfrequentelement","number":null,"title":"18 NOV 1838 Frequency of the Most Frequent Element","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"18-NOV 1838 Frequency of the Most Frequent Element.py","code":"class Solution:\n    def maxFrequency(self, nums: List[int], k: int) -> int:\n        nums.sort()\n        left, result, currentSum = 0, 0, 0\n        for right in range(len(nums)):\n            target = nums[right]\n            currentSum += target\n            while ((right - left + 1) * target) - currentSum > k:\n                currentSum -= nums[left]\n                left += 1\n            result = max(result, right - left + 1)\n        return result","hash":"c6db91c88d277fa50ba04c4701c3ed5d5c6182c67e5ca0a92efd509ed1c8ab05","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/18-NOV 1838 Frequency of the Most Frequent Element.py"}]}],"sources":["solutions"]},"topic-18oct2050parallelcoursesiii":{"key":"topic-18oct2050parallelcoursesiii","number":null,"title":"18 OCT 2050 Parallel Courses III","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"18-OCT 2050 Parallel Courses III.py","code":"class Solution:\n    def minimumTime(self, n: int, relations: List[List[int]], time: List[int]) -> int:\n        indegree, graph, queue, maxTime, result = [0] * n, defaultdict(list), deque(), [0] * n, 0\n        for x, y in relations:\n            graph[x - 1].append(y - 1)\n            indegree[y - 1] += 1\n        for node in range(n):\n            if indegree[node] == 0:\n                queue.append(node)\n                maxTime[node] = time[node]\n                result = max(result, maxTime[node])\n        while queue:\n            node = queue.popleft()\n            for neighbour in graph[node]:\n                maxTime[neighbour] = max(maxTime[neighbour], maxTime[node] + time[neighbour])\n                result = max(result, maxTime[neighbour])\n                indegree[neighbour] -= 1\n                if indegree[neighbour] == 0:\n                    queue.append(neighbour)\n        return result","hash":"b9d6721d091f56523986c13088a5f62fd9b896e12cc581c5f7d43b1c6bbbd116","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/18-OCT 2050 Parallel Courses III.py"}]}],"sources":["solutions"]},"topic-18sep1337thekweakestrowsinamatrix":{"key":"topic-18sep1337thekweakestrowsinamatrix","number":null,"title":"18 SEP 1337 The K Weakest Rows in a Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"18-SEP 1337 The K Weakest Rows in a Matrix.py","code":"class Solution:\n    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:\n        result, soldierFreq = [], []\n        for index, row in enumerate(mat):\n            soldierFreq.append((row.count(1), index))\n        soldierFreq.sort()\n        return [i for freq, i in soldierFreq[:k]]","hash":"bc9b798f4eeff6aa78f63ecf9a617cee902eba150bdcf1c4c7f84adb348058ef","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/18-SEP 1337 The K Weakest Rows in a Matrix.py"}]}],"sources":["solutions"]},"topic-19aug1489findcriticalandpseudocriticaledgesinminimumspanningtree":{"key":"topic-19aug1489findcriticalandpseudocriticaledgesinminimumspanningtree","number":null,"title":"19 AUG 1489 Find Critical and Pseudo Critical Edges in Minimum Spanning Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"19-AUG 1489 Find Critical and Pseudo-Critical Edges in Minimum Spanning Tree.py","code":"class UnionFind:\n    def __init__(self, n):\n        self._parent = list(range(n))\n        self._size = [1] * n\n        self.maxSize = 1\n    \n    # Finds the root of x\n    def find(self, x):\n        if x != self._parent[x]:\n            self._parent[x] = self.find(self._parent[x])\n        return self._parent[x]\n    \n    # Connects x and y\n    def union(self, x, y):\n        rootX, rootY = self.find(x), self.find(y)\n        if rootX != rootY:\n            if self._size[rootX] < self._size[rootY]:\n                rootX, rootY = rootY, rootX\n            self._parent[rootY] = rootX\n            self._size[rootX] += self._size[rootY]\n            self.maxSize = max(self.maxSize, self._size[rootX])\n            return True\n        return False\n\nclass Solution:\n    def findCriticalAndPseudoCriticalEdges(self, n: int, edges: List[List[int]]) -> List[List[int]]:\n        newEdges = [(edge[0], edge[1], edge[2], index) for index, edge in enumerate(edges)]\n        newEdges.sort(key = lambda x:x[2])\n        # Find Minimum Spanning Tree\n        mstWeight, uf = 0, UnionFind(n)\n        for u, v, w, _ in newEdges:\n            if uf.union(u, v):\n                mstWeight += w\n        # Check each edge for critical and pseudo-critical\n        critical, pseudoCritical = [], []\n        for u, v, w, i in newEdges:\n            # Ignore this edge and calculate MST weight\n            weightIgnore, ufIgnore = 0, UnionFind(n)\n            for x, y, wIgnore, j in newEdges:\n                if i != j and ufIgnore.union(x, y):\n                    weightIgnore += wIgnore\n            # If the graph is disconnected or the total weight is greater,\n            # the edge is critical\n            if ufIgnore.maxSize < n or weightIgnore > mstWeight:\n                critical.append(i)\n                continue\n            # Force this edge and calculate MST weight\n            weightForce, ufForce = w, UnionFind(n)\n            ufForce.union(u, v)\n            for x, y, wForce, j in newEdges:\n                if i != j and ufForce.union(x, y):\n                    weightForce += wForce\n            # If total weight is the same, the edge is pseudo-critical\n            if weightForce == mstWeight:\n                pseudoCritical.append(i)\n        return [critical, pseudoCritical]","hash":"2b1f10e4bf09bd52777c6d4b9651ca812ce1d1a57b60e8d191d4b38e22efa36e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/19-AUG 1489 Find Critical and Pseudo-Critical Edges in Minimum Spanning Tree.py"}]}],"sources":["solutions"]},"topic-19jul435nonoverlappingintervals":{"key":"topic-19jul435nonoverlappingintervals","number":null,"title":"19 JUL 435 Non overlapping Intervals","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"19-JUL 435 Non-overlapping Intervals.py","code":"class Solution:\n    def eraseOverlapIntervals(self, intervals: List[List[int]]) -> int:\n        intervalsLength = len(intervals)\n        if intervalsLength == 0:\n            return 0\n        intervals.sort(key = lambda x : x[1])\n        count = 1\n        end = intervals[0][1]\n        for i in range(1, intervalsLength):\n            if intervals[i][0] >= end:\n                end = intervals[i][1]\n                count += 1\n        return intervalsLength - count","hash":"18e3cfd4e30de75c03a3f1fb1f2d641841b0db92bc53ecacee7e7877c8f52ec8","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/19-JUL 435 Non-overlapping Intervals.py"}]}],"sources":["solutions"]},"topic-19jun1732findthehighestaltitude":{"key":"topic-19jun1732findthehighestaltitude","number":null,"title":"19 JUN 1732 Find the Highest Altitude","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"19-JUN 1732 Find the Highest Altitude.py","code":"class Solution:\n    def largestAltitude(self, gain: List[int]) -> int:\n        currentAltitude, maxAltitude = 0, 0\n        for g in gain:\n            currentAltitude += g\n            maxAltitude = max(maxAltitude, currentAltitude)\n        return maxAltitude","hash":"1d48ea3275bc7e8be2ed03d18e343fb7f44609c31e2e7682d3b580f1e132e18d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/19-JUN 1732 Find the Highest Altitude.py"}]}],"sources":["solutions"]},"topic-19may785isgraphbipartite":{"key":"topic-19may785isgraphbipartite","number":null,"title":"19 MAY 785 Is Graph Bipartite","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"19-MAY 785 Is Graph Bipartite.py","code":"class Solution:\n    def isBipartite(self, graph: List[List[int]]) -> bool:\n        nodeColor = [None for _ in range(len(graph))]\n        for node in range(len(graph)):\n            if nodeColor[node] is None:\n                stack = deque([node,])\n                nodeColor[node] = 0\n                while stack:\n                    tempNode = stack.pop()\n                    for neighbour in graph[tempNode]:\n                        if nodeColor[neighbour] is None:\n                            stack.append(neighbour)\n                            nodeColor[neighbour] = nodeColor[tempNode] ^ 1\n                        elif nodeColor[neighbour] == nodeColor[tempNode]:\n                            return False\n        return True","hash":"8d166f387c224d76795c52c921fff073bda8d7536b780dbb94fed84452c38015","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/19-MAY 785 Is Graph Bipartite.py"}]}],"sources":["solutions"]},"topic-19nov1887reductionoperationstomakethearrayelementsequal":{"key":"topic-19nov1887reductionoperationstomakethearrayelementsequal","number":null,"title":"19 NOV 1887 Reduction Operations to Make the Array Elements Equal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"19-NOV 1887 Reduction Operations to Make the Array Elements Equal.py","code":"class Solution:\n    def reductionOperations(self, nums: List[int]) -> int:\n        freqMap = Counter(nums)\n        distinctNums = sorted(set(nums))\n        result = 0\n        for i, num in enumerate(distinctNums[1:], start=1):\n            result += i * freqMap[num]\n        return result","hash":"fe8ce46cc1984626f18b852b8f25922cf36d17c656e83704fe44f0b8d8b7aeb6","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/19-NOV 1887 Reduction Operations to Make the Array Elements Equal.py"}]}],"sources":["solutions"]},"topic-19oct844backspacestringcompare":{"key":"topic-19oct844backspacestringcompare","number":null,"title":"19 OCT 844 Backspace String Compare","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"19-OCT 844 Backspace String Compare.py","code":"class Solution:\n    def backspaceCompare(self, S: str, T: str) -> bool:\n        def trimmedString(s):\n            skip = 0\n            for x in s[::-1]:\n                if x == '#':\n                    skip += 1\n                elif skip:\n                    skip -= 1\n                else:\n                    yield x\n        return all(x == y for x, y in zip_longest(trimmedString(S), trimmedString(T)))","hash":"f7c85b4bf4f271138e9860a39e392e8400fae7c57bc1eaa6e39124430e6e65f4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/19-OCT 844 Backspace String Compare.py"}]}],"sources":["solutions"]},"topic-19sep287findtheduplicatenumber":{"key":"topic-19sep287findtheduplicatenumber","number":null,"title":"19 SEP 287 Find the Duplicate Number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"19-SEP 287 Find the Duplicate Number.py","code":"class Solution:\n    def findDuplicate(self, nums: List[int]) -> int:\n        tortoise = hare = nums[0]\n        while True:\n            tortoise = nums[tortoise]\n            hare = nums[nums[hare]]\n            if tortoise == hare:\n                break\n        tortoise = nums[0]\n        while tortoise != hare:\n            tortoise = nums[tortoise]\n            hare = nums[hare]\n        return hare","hash":"c8039f0bc89c7388f23c8d9588250ca6de2548a0b31e099551a52db9ee869e02","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/19-SEP 287 Find the Duplicate Number.py"}]}],"sources":["solutions"]},"topic-20aug1203sortitemsbygroupsrespectingdependencies":{"key":"topic-20aug1203sortitemsbygroupsrespectingdependencies","number":null,"title":"20 AUG 1203 Sort Items by Groups Respecting Dependencies","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"20-AUG 1203 Sort Items by Groups Respecting Dependencies.py","code":"class Solution:\n    def sortItems(self, n: int, m: int, group: List[int], beforeItems: List[List[int]]) -> List[int]:\n        groupSet = set(group)\n        validGroupIndex = [i for i in range(max(m, n)) if i not in groupSet]\n        for index, g in enumerate(group):\n            if g == -1:\n                group[index] = validGroupIndex[-1]\n                validGroupIndex.pop()\n        itemsGraph, groupGraph, itemsInDegree, groupInDegree = defaultdict(list), defaultdict(list), [0] * n, [0] * n\n        for index, node in enumerate(beforeItems):\n            for item in node:\n                itemsGraph[item].append(index)\n                itemsInDegree[index] += 1\n                if group[item] != group[index]:\n                    groupGraph[group[item]].append(group[index])\n                    groupInDegree[group[index]] += 1\n        \n        def topologicalSort(graph, inDegree):\n            queue = deque([node for node, degree in enumerate(inDegree) if degree == 0])\n            result = []\n            while queue:\n                node = queue.popleft()\n                result.append(node)\n                for neighbour in graph[node]:\n                    inDegree[neighbour] -= 1\n                    if inDegree[neighbour] == 0:\n                        queue.append(neighbour)\n            return [] if len(result) != len(graph) else result\n        \n        itemsOrder, groupOrder = topologicalSort(itemsGraph, itemsInDegree), topologicalSort(groupGraph, groupInDegree)\n        if itemsOrder == [] or groupOrder == []:\n            return []\n        itemsGroup = defaultdict(list)\n        for item in itemsOrder:\n            itemsGroup[group[item]].append(item)\n        result = []\n        for g in groupOrder:\n            result.extend(itemsGroup[g])\n        return result","hash":"5939fe226bf331b51377bb12359d88b032255859f521afda8c5752659459516d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/20-AUG 1203 Sort Items by Groups Respecting Dependencies.py"}]}],"sources":["solutions"]},"topic-20jul735asteroidcollision":{"key":"topic-20jul735asteroidcollision","number":null,"title":"20 JUL 735 Asteroid Collision","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"20-JUL 735 Asteroid Collision.py","code":"class Solution:\n    def asteroidCollision(self, asteroids: List[int]) -> List[int]:\n        result = []\n        for asteroid in asteroids:\n            while result and asteroid < 0 < result[-1]:\n                if result[-1] < -asteroid:\n                    result.pop()\n                    continue\n                elif result[-1] == -asteroid:\n                    result.pop()\n                break\n            else:\n                result.append(asteroid)\n        return result","hash":"a5f2509a613af4a72c12a8477e172819c21f36578c765f1d38600926bc132123","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/20-JUL 735 Asteroid Collision.py"}]}],"sources":["solutions"]},"topic-20jun2090kradiussubarrayaverages":{"key":"topic-20jun2090kradiussubarrayaverages","number":null,"title":"20 JUN 2090 K Radius Subarray Averages","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"20-JUN 2090 K Radius Subarray Averages.py","code":"class Solution:\n    def getAverages(self, nums: List[int], k: int) -> List[int]:\n        currentSum, avgRange, N = 0, 2 * k + 1, len(nums)\n        result = [-1] * N\n        if N < avgRange:\n            return result\n        for i in range(avgRange):\n            currentSum += nums[i]\n        for i in range(k, N - k):\n            result[i] = currentSum // avgRange\n            currentSum += (nums[i + k + 1] - nums[i - k]) if i != N - k - 1 else 0\n        return result","hash":"fc23d3089130647a8fac59acced0fa75382069e68606385a8dd1e1a39f9ed266","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/20-JUN 2090 K Radius Subarray Averages.py"}]}],"sources":["solutions"]},"topic-20may399evaluatedivision":{"key":"topic-20may399evaluatedivision","number":null,"title":"20 MAY 399 Evaluate Division","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"20-MAY 399 Evaluate Division.py","code":"class Solution:\n    def calcEquation(self, equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:\n        graph = defaultdict()\n        for index, (source, destination) in enumerate(equations):\n            if source not in graph:\n                graph[source] = defaultdict(int)\n            graph[source][destination] = float(values[index])\n            if destination not in graph:\n                graph[destination] = defaultdict(int)\n            graph[destination][source] = float(1 / values[index])\n        def dfs(source, destination, currentValue, visitedSet):\n            nonlocal graph\n            if source in visitedSet:\n                return\n            visitedSet.add(source)\n            if source == destination:\n                self.currentResult = currentValue\n                return\n            for neighbour, value in graph[source].items():\n                dfs(neighbour, destination, currentValue * value, visitedSet)\n        result = []\n        for source, destination in queries:\n            if source not in graph or destination not in graph:\n                result.append(-1.0)\n            elif source == destination:\n                result.append(1.0)\n            elif destination in graph[source]:\n                result.append(graph[source][destination])\n            else:\n                self.currentResult = -1.0\n                dfs(source, destination, 1.0, set())\n                result.append(self.currentResult)\n        return result","hash":"7099f07a76c010b914c4aa2962260070897efd2dadd3d9f8e3fb6b9663b3e59d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/20-MAY 399 Evaluate Division.py"}]}],"sources":["solutions"]},"topic-20nov2391minimumamountoftimetocollectgarbage":{"key":"topic-20nov2391minimumamountoftimetocollectgarbage","number":null,"title":"20 NOV 2391 Minimum Amount of Time to Collect Garbage","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"20-NOV 2391 Minimum Amount of Time to Collect Garbage.py","code":"class Solution:\n    def garbageCollection(self, garbage: List[str], travel: List[int]) -> int:\n        # Array to store the prefix sum in travel.\n        prefixSum = [0] * (len(travel) + 1)\n        prefixSum[1] = travel[0]\n        for i in range(1, len(travel)):\n            prefixSum[i + 1] = prefixSum[i] + travel[i]\n        # Map to store garbage type to the last house index.\n        garbageLastPosition = defaultdict(int)\n        # Map to store the total count of each type of garbage in all houses.\n        garbageCount = defaultdict(int)\n        for i in range(len(garbage)):\n            for char in garbage[i]:\n                garbageLastPosition[char] = i\n                garbageCount[char] += 1\n        result, garbageTypes = 0, ['M', 'P', 'G']\n        for garbageType in garbageTypes:\n            if garbageType in garbageCount:\n                result += prefixSum[garbageLastPosition[garbageType]] + garbageCount[garbageType]\n        return result","hash":"8055039bb368eaee42219b0b3b078ff05686549426b307dba3f7b290845e3cd9","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/20-NOV 2391 Minimum Amount of Time to Collect Garbage.py"}]}],"sources":["solutions"]},"topic-20oct341flattennestedlistiterator":{"key":"topic-20oct341flattennestedlistiterator","number":null,"title":"20 OCT 341 Flatten Nested List Iterator","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"20-OCT 341 Flatten Nested List Iterator.py","code":"# \"\"\"\n# This is the interface that allows for creating nested lists.\n# You should not implement it, or speculate about its implementation\n# \"\"\"\n#class NestedInteger:\n#    def isInteger(self) -> bool:\n#        \"\"\"\n#        @return True if this NestedInteger holds a single integer, rather than a nested list.\n#        \"\"\"\n#\n#    def getInteger(self) -> int:\n#        \"\"\"\n#        @return the single integer that this NestedInteger holds, if it holds a single integer\n#        Return None if this NestedInteger holds a nested list\n#        \"\"\"\n#\n#    def getList(self) -> [NestedInteger]:\n#        \"\"\"\n#        @return the nested list that this NestedInteger holds, if it holds a nested list\n#        Return None if this NestedInteger holds a single integer\n#        \"\"\"\n\nclass NestedIterator:\n    def __init__(self, nestedList: [NestedInteger]):\n        self._data = nestedList[::-1]\n    \n    def next(self) -> int:\n        return self._data.pop().getInteger()\n    \n    def hasNext(self) -> bool:\n        while self._data and not self._data[-1].isInteger():\n            self._data += self._data.pop().getList()[::-1]\n        return len(self._data) > 0\n\n# Your NestedIterator object will be instantiated and called as such:\n# i, v = NestedIterator(nestedList), []\n# while i.hasNext(): v.append(i.next())","hash":"51bfed89977d2fcf0da7c9e8df830eeccf74cbedf986509d4e069397972978b2","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/20-OCT 341 Flatten Nested List Iterator.py"}]}],"sources":["solutions"]},"topic-20sep1658minimumoperationstoreducextozero":{"key":"topic-20sep1658minimumoperationstoreducextozero","number":null,"title":"20 SEP 1658 Minimum Operations to Reduce X to Zero","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"20-SEP 1658 Minimum Operations to Reduce X to Zero.py","code":"class Solution:\n    def minOperations(self, nums: List[int], x: int) -> int:\n        currentSum, n, minLength, left = sum(nums), len(nums), float('inf'), 0\n        for right in range(n):\n            currentSum -= nums[right]\n            while currentSum < x and left <= right:\n                currentSum += nums[left]\n                left += 1\n            if currentSum == x:\n                minLength = min(minLength, n - 1 - right + left)\n        return minLength if minLength != float('inf') else -1","hash":"18b5a9805cf135883810c789e0878212ccfd44d92be9e1869e46fe0232aa45aa","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/20-SEP 1658 Minimum Operations to Reduce X to Zero.py"}]}],"sources":["solutions"]},"topic-21aug459repeatedsubstringpattern":{"key":"topic-21aug459repeatedsubstringpattern","number":null,"title":"21 AUG 459 Repeated Substring Pattern","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"21-AUG 459 Repeated Substring Pattern.py","code":"class Solution:\n    def repeatedSubstringPattern(self, s: str) -> bool:\n        return s in (s + s)[1:-1]","hash":"c77ad16cb7397f22998c79c59588491b9745e1bc5ce2a3b5c0af46c8e03015e7","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/21-AUG 459 Repeated Substring Pattern.py"}]}],"sources":["solutions"]},"topic-21jul673numberoflongestincreasingsubsequence":{"key":"topic-21jul673numberoflongestincreasingsubsequence","number":null,"title":"21 JUL 673 Number of Longest Increasing Subsequence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"21-JUL 673 Number of Longest Increasing Subsequence.py","code":"class Solution:\n    def findNumberOfLIS(self, nums):\n        N = len(nums)\n        if N <= 1: return N\n        lengths = [0] * N #lengths[i] = longest ending in nums[i]\n        counts = [1] * N #count[i] = number of longest ending in nums[i]\n        for j, num in enumerate(nums):\n            for i in range(j):\n                if nums[i] < nums[j]:\n                    if lengths[i] >= lengths[j]:\n                        lengths[j] = 1 + lengths[i]\n                        counts[j] = counts[i]\n                    elif lengths[i] + 1 == lengths[j]:\n                        counts[j] += counts[i]\n        longest = max(lengths)\n        return sum(c for i, c in enumerate(counts) if lengths[i] == longest)","hash":"554da2a45b4ce59c9970759655cf9148dc3e19721e8d5a6a911468421e9ee088","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/21-JUL 673 Number of Longest Increasing Subsequence.py"}]}],"sources":["solutions"]},"topic-21jun2448minimumcosttomakearrayequal":{"key":"topic-21jun2448minimumcosttomakearrayequal","number":null,"title":"21 JUN 2448 Minimum Cost to Make Array Equal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"21-JUN 2448 Minimum Cost to Make Array Equal.py","code":"class Solution:\n    def minCost(self, nums: List[int], costs: List[int]) -> int:\n        # Sort integers by values.\n        numsAndCosts = sorted([num, cost] for num, cost in zip(nums, costs))\n        n = len(costs)\n        # Get the prefix sum array of the costs.\n        prefixCost = [0] * n\n        prefixCost[0] = numsAndCosts[0][1]\n        for i in range(1, n): \n            prefixCost[i] = numsAndCosts[i][1] + prefixCost[i - 1]\n        # Then we try every integer nums[i] and make every element equals nums[i],\n        # Start with nums[0]\n        totalCost = 0\n        for i in range(1, n):\n            totalCost += numsAndCosts[i][1] * (numsAndCosts[i][0] - numsAndCosts[0][0])\n        result = totalCost\n        # Then we try nums[1], nums[2] and so on. The cost difference is made by the change of\n        # two parts: 1. prefix sum of costs. 2. suffix sum of costs. \n        # During the iteration, record the minimum cost we have met.\n        for i in range(1, n):\n            gap = numsAndCosts[i][0] - numsAndCosts[i - 1][0]\n            totalCost += prefixCost[i - 1] * gap\n            totalCost -= gap * (prefixCost[n - 1] - prefixCost[i - 1])\n            result = min(result, totalCost)\n        return result","hash":"5b027aa1b7b5167da1a23f63e315de02cd666f100b9dd4edfe38e2f411dc0c18","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/21-JUN 2448 Minimum Cost to Make Array Equal.py"}]}],"sources":["solutions"]},"topic-21may934shortestbridge":{"key":"topic-21may934shortestbridge","number":null,"title":"21 MAY 934 Shortest Bridge","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"21-MAY 934 Shortest Bridge.py","code":"class Solution:\n    def shortestBridge(self, A: List[List[int]]) -> int:\n        rows, cols = len(A), len(A[0])\n        \n        def neighbours(r, c):\n            for row, col in [(r - 1, c), (r, c - 1), (r + 1, c), (r, c + 1)]:\n                if 0 <= row < rows and 0 <= col < cols:\n                    yield row, col\n        \n        def getComponents():\n            visited, components = set(), []\n            for r, row in enumerate(A):\n                for c, val in enumerate(row):\n                    if val == 1 and (r, c) not in visited:\n                        seen, stack = {(r, c)}, deque([(r, c),])\n                        while stack:\n                            node = stack.pop()\n                            for nei in neighbours(*node):\n                                if nei not in seen and A[nei[0]][nei[1]] == 1:\n                                    seen.add(nei)\n                                    stack.append(nei)\n                        visited |= seen\n                        components.append(seen)\n            return components\n        \n        source, target = getComponents()\n        queue, visited = deque([(node, 0) for node in source]), set(source)\n        while queue:\n            node, d = queue.popleft()\n            if node in target:\n                return d - 1\n            for nei in neighbours(*node):\n                if nei not in visited:\n                    visited.add(nei)\n                    queue.append((nei, d + 1))","hash":"356aed0ccdffe4469ffd41563905a23338b37804eee1545590b0224fc3aa7050","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/21-MAY 934 Shortest Bridge.py"}]}],"sources":["solutions"]},"topic-21oct1425constrainedsubsequencesum":{"key":"topic-21oct1425constrainedsubsequencesum","number":null,"title":"21 OCT 1425 Constrained Subsequence Sum","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"21-OCT 1425 Constrained Subsequence Sum.py","code":"class Solution:\n    def constrainedSubsetSum(self, nums: List[int], k: int) -> int:\n        heap = [(-nums[0], 0)]\n        ans = nums[0]\n        \n        for i in range(1, len(nums)):\n            while i - heap[0][1] > k:\n                heapq.heappop(heap)\n\n            curr = max(0, -heap[0][0]) + nums[i]\n            ans = max(ans, curr)\n            heapq.heappush(heap, (-curr, i))\n\n        return ans","hash":"6615891491ee89e2887d042309a5e66024435a4ab2bf8b4373651976cda0a8c6","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/21-OCT 1425 Constrained Subsequence Sum.py"}]}],"sources":["solutions"]},"topic-21sep4medianoftwosortedarrays":{"key":"topic-21sep4medianoftwosortedarrays","number":null,"title":"21 SEP 4 Median of Two Sorted Arrays","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"21-SEP 4 Median of Two Sorted Arrays.py","code":"class Solution:\n    def findMedianSortedArrays(self, A: List[int], B: List[int]) -> float:\n        m, n = len(A), len(B)\n        if m > n:\n            A, B, m, n = B, A, n, m\n        if n == 0:\n            raise ValueError\n        iMin, iMax, halfLength = 0, m, (m + n + 1) // 2\n        while iMin <= iMax:\n            i = (iMin + iMax) // 2\n            j = halfLength - i\n            if i < m and B[j - 1] > A[i]:\n                iMin = i + 1\n            elif i > 0 and A[i - 1] > B[j]:\n                iMax = i - 1\n            else:\n                if i == 0:\n                    maxOfLeft = B[j - 1]\n                elif j == 0:\n                    maxOfLeft = A[i - 1]\n                else:\n                    maxOfLeft = max(A[i - 1], B[j - 1])\n                if (m + n) % 2 == 1:\n                    return maxOfLeft\n                if i == m:\n                    minOfRight = B[j]\n                elif j == n:\n                    minOfRight = A[i]\n                else:\n                    minOfRight = min(A[i], B[j])\n                return (maxOfLeft + minOfRight) / 2.0","hash":"8f9d0433123dac32b253f155803e80646d4b79670305ace0ba1e9324a4287de0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/21-SEP 4 Median of Two Sorted Arrays.py"}]}],"sources":["solutions"]},"topic-22aug168excelsheetcolumntitle":{"key":"topic-22aug168excelsheetcolumntitle","number":null,"title":"22 AUG 168 Excel Sheet Column Title","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"22-AUG 168 Excel Sheet Column Title.py","code":"class Solution:\n    def convertToTitle(self, n: int) -> str:\n        result = []\n        while n:\n            result.append(chr(ord('A') + ((n - 1) % 26)))\n            n = (n - 1) // 26\n        return ''.join(result[::-1])","hash":"c71d8864d31c861c8fa60c19721c51400f5705cd9e48029f11154153895478bb","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/22-AUG 168 Excel Sheet Column Title.py"}]}],"sources":["solutions"]},"topic-22jul688knightprobabilityinchessboard":{"key":"topic-22jul688knightprobabilityinchessboard","number":null,"title":"22 JUL 688 Knight Probability in Chessboard","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"22-JUL 688 Knight Probability in Chessboard.py","code":"class Solution:\n    def knightProbability(self, N: int, K: int, r: int, c: int) -> float:\n        VALID_MOVES = [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]\n        dp = [[0] * N for _ in range(N)]\n        dp[r][c] = 1\n        for _ in range(K):\n            dp2 = [[0] * N for _ in range(N)]\n            for r, row in enumerate(dp):\n                for c, val in enumerate(row):\n                    for dr, dc in VALID_MOVES:\n                        if 0 <= r + dr < N and 0 <= c + dc < N:\n                            dp2[r + dr][c + dc] += val / 8.0\n            dp = dp2\n        return sum(map(sum, dp))","hash":"39cd5bb3ad077d49abe0164534f467c6b743f99a05caff787f3cc978609e93fd","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/22-JUL 688 Knight Probability in Chessboard.py"}]}],"sources":["solutions"]},"topic-22jun714besttimetobuyandsellstockwithtransactionfee":{"key":"topic-22jun714besttimetobuyandsellstockwithtransactionfee","number":null,"title":"22 JUN 714 Best Time to Buy and Sell Stock with Transaction Fee","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"22-JUN 714 Best Time to Buy and Sell Stock with Transaction Fee.py","code":"class Solution:\n    def maxProfit(self, prices: List[int], fee: int) -> int:\n        cash, hold = 0, -prices[0]\n        for i in range(1, len(prices)):\n            cash = max(cash, hold + prices[i] - fee)\n            hold = max(hold, cash - prices[i])\n        return cash","hash":"4859d75d29da633527103653813228624a4c5b28830f24714c06375d76f0bfdc","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/22-JUN 714 Best Time to Buy and Sell Stock with Transaction Fee.py"}]}],"sources":["solutions"]},"topic-22may347topkfrequentelements":{"key":"topic-22may347topkfrequentelements","number":null,"title":"22 MAY 347 Top K Frequent Elements","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"22-MAY 347 Top K Frequent Elements.py","code":"class Solution:\n    def topKFrequent(self, nums: List[int], k: int) -> List[int]:\n        # O(1) time \n        if k == len(nums):\n            return nums\n        # 1. build hash map : character and how often it appears\n        # O(N) time\n        count = Counter(nums)\n        # 2-3. build heap of top k frequent elements and\n        # convert it into an output array\n        # O(N log k) time\n        return heapq.nlargest(k, count.keys(), key=count.get)","hash":"6afc586fcaa718080c12aeaffdf72e0ba792739b2c0f64114cd7d892d7536464","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/22-MAY 347 Top K Frequent Elements.py"}]}],"sources":["solutions"]},"topic-22oct1793maximumscoreofagoodsubarray":{"key":"topic-22oct1793maximumscoreofagoodsubarray","number":null,"title":"22 OCT 1793 Maximum Score of a Good Subarray","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"22-OCT 1793 Maximum Score of a Good Subarray.py","code":"class Solution:\n    def maximumScore(self, nums: List[int], k: int) -> int:\n        def solve(nums, k):\n            n = len(nums)\n            left = [0] * k\n            curr_min = inf\n            for i in range(k - 1, -1, -1):\n                curr_min = min(curr_min, nums[i])\n                left[i] = curr_min\n\n            right = []\n            curr_min = inf\n            for i in range(k, n):\n                curr_min = min(curr_min, nums[i])\n                right.append(curr_min)\n\n            ans = 0\n            for j in range(len(right)):\n                curr_min = right[j]\n                i = bisect_left(left, curr_min)\n                size = (k + j) - i + 1\n                ans = max(ans, curr_min * size)\n                \n            return ans\n        \n        return max(solve(nums, k), solve(nums[::-1], len(nums) - k - 1))","hash":"f72d5411dd0b383940f48fa3fafd3b7b3017b2a8011f0690e47591d3274db3fa","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/22-OCT 1793 Maximum Score of a Good Subarray.py"}]}],"sources":["solutions"]},"topic-22sep392issubsequence":{"key":"topic-22sep392issubsequence","number":null,"title":"22 SEP 392 Is Subsequence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"22-SEP 392 Is Subsequence.py","code":"class Solution:\n    def isSubsequence(self, s: str, t: str) -> bool:\n        i = j = 0\n        while i < len(s) and j < len(t):\n            if s[i] == t[j]:\n                i += 1\n                j += 1\n            else:\n                j += 1\n        return i == len(s)","hash":"88ae4b00dd4cb033a68cb2a627ccd52e74052b920d2a22f891eb68591a137432","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/22-SEP 392 Is Subsequence.py"}]}],"sources":["solutions"]},"topic-23aug767reorganizestring":{"key":"topic-23aug767reorganizestring","number":null,"title":"23 AUG 767 Reorganize String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"23-AUG 767 Reorganize String.py","code":"class Solution:\n    def reorganizeString(self, s: str) -> str:\n        charFreqMap = Counter(s)\n        maxFreq, maxFreqChar = 0, ''\n        for char, count in charFreqMap.items():\n            if count > maxFreq:\n                maxFreq = count\n                maxFreqChar = char\n        if maxFreq > (len(s) + 1) // 2:\n            return ''\n        ans = [''] * len(s)\n        index = 0\n\n        # Place the most frequent letter\n        while charFreqMap[maxFreqChar] != 0:\n            ans[index] = maxFreqChar\n            index += 2\n            charFreqMap[maxFreqChar] -= 1\n\n        # Place rest of the letters in any order\n        for char, count in charFreqMap.items():\n            while count > 0:\n                if index >= len(s):\n                    index = 1\n                ans[index] = char\n                index += 2\n                count -= 1\n\n        return ''.join(ans)","hash":"ab0d193846a6d0423931448cefe4b7183bdad67dba9adfc70291f6e6d2e04566","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/23-AUG 767 Reorganize String.py"}]}],"sources":["solutions"]},"topic-23jul894allpossiblefullbinarytrees":{"key":"topic-23jul894allpossiblefullbinarytrees","number":null,"title":"23 JUL 894 All Possible Full Binary Trees","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"23-JUL 894 All Possible Full Binary Trees.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def allPossibleFBT(self, N: int) -> List[Optional[TreeNode]]:\n        self.memo = {0: [], 1: [TreeNode(0)]}\n        def recurse(n: int):\n            if n not in self.memo:\n                result = []\n                for x in range(n):\n                    y = n - 1 - x\n                    for left in recurse(x):\n                        for right in recurse(y):\n                            result.append(TreeNode(0, left, right))\n                self.memo[n] = result\n            return self.memo[n]\n        recurse(N)\n        return self.memo[N]","hash":"d5d1906454383d248fc1d8aeab7ee91de63466e3e5036bb545d4e4efb59abaf1","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/23-JUL 894 All Possible Full Binary Trees.py"}]}],"sources":["solutions"]},"topic-23jun1027longestarithmeticsubsequence":{"key":"topic-23jun1027longestarithmeticsubsequence","number":null,"title":"23 JUN 1027 Longest Arithmetic Subsequence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"23-JUN 1027 Longest Arithmetic Subsequence.py","code":"class Solution:\n    def longestArithSeqLength(self, nums: List[int]) -> int:\n        dp = defaultdict(lambda:1)\n        for right in range(len(nums)):\n            for left in range(right):\n                diff = nums[right] - nums[left]\n                dp[(right, diff)] = dp[(left, diff)] + 1\n        return max(dp.values())","hash":"6f4e53910b346c247fdde8f626334e0351867870594f28918ac977a97967fb30","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/23-JUN 1027 Longest Arithmetic Subsequence.py"}]}],"sources":["solutions"]},"topic-23may703kthlargestelementinastream":{"key":"topic-23may703kthlargestelementinastream","number":null,"title":"23 MAY 703 Kth Largest Element in a Stream","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"23-MAY 703 Kth Largest Element in a Stream.py","code":"class KthLargest:\n\n    def __init__(self, k: int, nums: List[int]):\n        self._k = k\n        self._heap = nums\n        heapify(self._heap)\n\n    def add(self, val: int) -> int:\n        heappush(self._heap, val)\n        while len(self._heap) > self._k:\n            heappop(self._heap)\n        return self._heap[0]\n\n\n# Your KthLargest object will be instantiated and called as such:\n# obj = KthLargest(k, nums)\n# param_1 = obj.add(val)","hash":"872adbd6808e1f1c6189434cb612de99e7a23e89018ea29f945422d63461aa64","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/23-MAY 703 Kth Largest Element in a Stream.py"}]}],"sources":["solutions"]},"topic-23oct342poweroffour":{"key":"topic-23oct342poweroffour","number":null,"title":"23 OCT 342 Power of Four","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"23-OCT 342 Power of Four.py","code":"import math\n\nclass Solution:\n    def isPowerOfFour(self, num: int) -> bool:\n        if num <= 0:\n            return False\n        else:\n            log4 = log(abs(num), 4)\n            if math.floor(log4) == math.ceil(log4):\n                return True\n            return False","hash":"c3412e91b20455605911e219fa32a015b757be622ab659686e2df521d0b7b693","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/23-OCT 342 Power of Four.py"}]}],"sources":["solutions"]},"topic-23sep1048longeststringchain":{"key":"topic-23sep1048longeststringchain","number":null,"title":"23 SEP 1048 Longest String Chain","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"23-SEP 1048 Longest String Chain.py","code":"class Solution:\n    def longestStrChain(self, words: List[str]) -> int:\n        dp, longestWordSequenceLength = defaultdict(int), 1\n        words.sort(key = lambda x:len(x))\n        for word in words:\n            presentLength = 1\n            # Find all possible predecessors for the current word by removing one letter at a time.\n            for i in range(len(word)):\n                predecessor = word[:i] + word[i+1:]\n                presentLength = max(presentLength, dp[predecessor] + 1)\n            dp[word] = presentLength\n            longestWordSequenceLength = max(longestWordSequenceLength, presentLength)\n        return longestWordSequenceLength","hash":"b6d8ba14951979e9ff7a571360221ebdb8619c972c92d7a990ee47f6da9d5a77","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/23-SEP 1048 Longest String Chain.py"}]}],"sources":["solutions"]},"topic-24aug68textjustification":{"key":"topic-24aug68textjustification","number":null,"title":"24 AUG 68 Text Justification","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"24-AUG 68 Text Justification.py","code":"class Solution:\n    def fullJustify(self, words: List[str], maxWidth: int) -> List[str]:\n        def getWords(i):\n            currentLine = []\n            currentLength = 0\n            while i < len(words) and currentLength + len(words[i]) <= maxWidth:\n                currentLine.append(words[i])\n                currentLength += len(words[i]) + 1\n                i += 1\n            return currentLine\n        \n        def createLine(line, i):\n            baseLength = -1\n            for word in line:\n                baseLength += len(word) + 1\n            extraSpaces = maxWidth - baseLength\n            if len(line) == 1 or i == len(words):\n                return \" \".join(line) + \" \" * extraSpaces\n            wordCount = len(line) - 1\n            spacesPerWord = extraSpaces // wordCount\n            needsExtraSpace = extraSpaces % wordCount\n            for j in range(needsExtraSpace):\n                line[j] += \" \"\n            for j in range(wordCount):\n                line[j] += \" \" * spacesPerWord\n            return \" \".join(line)\n\n        result = []\n        i = 0\n        while i < len(words):\n            currentLine = getWords(i)\n            i += len(currentLine)\n            result.append(createLine(currentLine, i))\n        return result","hash":"d3c0acfbf7100b2f761ff173a92f8b7e6d09257888237e98dc5d0842dade2876","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/24-AUG 68 Text Justification.py"}]}],"sources":["solutions"]},"topic-24jul50powxn":{"key":"topic-24jul50powxn","number":null,"title":"24 JUL 50 Pow(x, n)","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"24-JUL 50 Pow(x, n).py","code":"class Solution:\n    def myPow(self, x: float, n: int) -> float:\n        def fastPower(x, n):\n            if n == 0:\n                return float(1)\n            temp = fastPower(x, n // 2)\n            if n % 2:\n                return float(temp * temp * x)\n            else:\n                return float(temp * temp)\n        if n < 0:\n            x = 1 / x\n            n = -n\n        return fastPower(x, n)","hash":"7f572ad35906ce21af97993fb648a7ec37d01c980b207f0c999f71d68ae35352","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/24-JUL 50 Pow(x, n).py"}]}],"sources":["solutions"]},"topic-24jun956tallestbillboard":{"key":"topic-24jun956tallestbillboard","number":null,"title":"24 JUN 956. Tallest Billboard","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"24-JUN 956. Tallest Billboard.py","code":"class Solution:\n    def tallestBillboard(self, rods: List[int]) -> int:\n        # dp[taller - shorter] = taller\n        dp = {0:0}\n        for r in rods:\n            # dp.copy() means we don't add r to these stands\n            newDp = dp.copy()\n            for diff, taller in dp.items():\n                shorter = taller - diff\n                # Add r to the taller stand, thus the height difference is increased to diff + r.\n                newDp[diff + r] = max(newDp.get(diff + r, 0), taller + r)\n                # Add r to the shorter stand, the height difference is expressed as abs(shorter + r - taller).\n                newDiff = abs(shorter + r - taller)\n                newTaller = max(shorter + r, taller)\n                newDp[newDiff] = max(newDp.get(newDiff, 0), newTaller)\n            dp = newDp\n        # return the maximum height with 0 difference\n        return dp.get(0, 0)","hash":"283becbcc33ab227d7aee5ae7f27c85726f33bb9caf6b6ee04156b6a8d9f26de","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/24-JUN 956. Tallest Billboard.py"}]}],"sources":["solutions"]},"topic-24may2542maximumsubsequencescore":{"key":"topic-24may2542maximumsubsequencescore","number":null,"title":"24 MAY 2542 Maximum Subsequence Score","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"24-MAY 2542 Maximum Subsequence Score.py","code":"class Solution:\n    def maxScore(self, nums1: List[int], nums2: List[int], k: int) -> int:\n        # Sort pair (nums1[i], nums2[i]) by nums2[i] in decreasing order.\n        pairs = [(a, b) for a, b in zip(nums1, nums2)]\n        pairs.sort(key = lambda x: -x[1])\n\n        # Use a min-heap to maintain the top k elements.\n        top_k_heap = [x[0] for x in pairs[:k]]\n        top_k_sum = sum(top_k_heap)\n        heapq.heapify(top_k_heap)\n\n        # The score of the first k pairs.\n        answer = top_k_sum * pairs[k - 1][1]\n\n        # Iterate over every nums2[i] as minimum from nums2.\n        for i in range(k, len(nums1)):\n            # Remove the smallest integer from the previous top k elements\n            # then add nums1[i] to the top k elements.\n            top_k_sum -= heapq.heappop(top_k_heap)\n            top_k_sum += pairs[i][0]\n            heapq.heappush(top_k_heap, pairs[i][0])\n            \n            # Update answer as the maximum score.\n            answer = max(answer, top_k_sum * pairs[i][1])\n        \n        return answer","hash":"66344077692944b5c993dbada2dfafd4c57dde5edbac4b3940aa8991be8c578a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/24-MAY 2542 Maximum Subsequence Score.py"}]}],"sources":["solutions"]},"topic-24oct515findlargestvalueineachtreerow":{"key":"topic-24oct515findlargestvalueineachtreerow","number":null,"title":"24 OCT 515 Find Largest Value in Each Tree Row","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"24-OCT 515 Find Largest Value in Each Tree Row.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def largestValues(self, root: TreeNode) -> List[int]:\n        heightCache = defaultdict(lambda : float('-inf'))\n        \n        def preorder(node, depth):\n            if not node:\n                return\n            heightCache[depth] = max(heightCache[depth], node.val)\n            preorder(node.left, depth + 1)\n            preorder(node.right, depth + 1)\n        \n        preorder(root, 0)\n        result = []\n        for i, val in sorted(heightCache.items()):\n            result.append(val)\n        return result","hash":"7c2ac292841748081875ce12694720108545b821f2a7d4395c26e7cbaa1ac60e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/24-OCT 515 Find Largest Value in Each Tree Row.py"}]}],"sources":["solutions"]},"topic-24sep799champagnetower":{"key":"topic-24sep799champagnetower","number":null,"title":"24 SEP 799 Champagne Tower","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"24-SEP 799 Champagne Tower.py","code":"class Solution:\n    def champagneTower(self, poured: int, query_row: int, query_glass: int) -> float:\n        tower = [[0] * k for k in range(1, 102)]\n        tower[0][0] = poured\n        for row in range(query_row + 1):\n            for col in range(row + 1):\n                remaining = (tower[row][col] - 1.0) / 2.0\n                if remaining > 0:\n                    tower[row + 1][col] += remaining\n                    tower[row + 1][col + 1] += remaining\n        return min(1, tower[query_row][query_glass])","hash":"70d7ff305df46a2d0767e18dd29fd9db57fd9d5196ccd9af948772ae657c39a8","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/24-SEP 799 Champagne Tower.py"}]}],"sources":["solutions"]},"topic-25aug97interleavingstring":{"key":"topic-25aug97interleavingstring","number":null,"title":"25 AUG 97 Interleaving String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"25-AUG 97 Interleaving String.py","code":"class Solution:\n    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:\n        s1Len, s2Len, s3Len = len(s1), len(s2), len(s3)\n        if s1Len + s2Len != s3Len:\n            return False\n        dp = [False] * (s2Len + 1)\n        for i in range(s1Len + 1):\n            for j in range(s2Len + 1):\n                if i == 0 and j == 0:\n                    dp[j] = True\n                elif i == 0:\n                    dp[j] = dp[j - 1] and s2[j - 1] == s3[i + j - 1]\n                elif j == 0:\n                    dp[j] = dp[j] and s1[i - 1] == s3[i + j - 1]\n                else:\n                    dp[j] = (dp[j - 1] and s2[j - 1] == s3[i + j - 1]) or (dp[j] and s1[i - 1] == s3[i + j - 1])\n        return dp[s2Len]","hash":"310665f514d239b101ab170ece4c7ccb3a07a106f24867e1f2f262ed9e46805b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/25-AUG 97 Interleaving String.py"}]}],"sources":["solutions"]}});
